# M3 regression test (todo.md HavokOS M3): run LPC snippets through the Star
# bytecode compiler + VM and compare each result against the live Pike
# reference's, frozen in two fixtures:
#   fixtures/cases/m3.expected.txt        the language-semantics cases of the
#                                          reference's own pike/tests/run_tests.pike
#                                          table (selection: m3_selection.txt)
#   fixtures/cases/m3_extra.expected.txt  this port's edge cases (m3_extra_cases.txt)
# Both were generated by tools/ref_cases.pike driving the reference driver on
# its test mudlib, which this test also runs against.
#
# Usage: powershell -File projects/havokos/tests/run_cases_test.ps1 [-Minilib E:\dsdev\havokos\pike\tests\minilib]
# (rebuild tools/run_cases.exe first if any compiler/VM .star file changed:
#   target/release/star.exe build projects/havokos/tools/run_cases.star -o projects/havokos/tools/run_cases.exe)
# Exits 0 when every case matches, 1 otherwise.
#
# Regenerating a fixture (only after confirming the *reference's* own
# behavior changed, never to paper over a Star-side diff):
#   pike tools/ref_cases.pike <havokos>/pike tests/fixtures/cases/m3_selection.txt   > tests/fixtures/cases/m3.expected.txt
#   pike tools/ref_cases.pike <havokos>/pike -extra tests/fixtures/cases/m3_extra_cases.txt > tests/fixtures/cases/m3_extra.expected.txt

param([string]$Minilib = "E:\dsdev\havokos\pike\tests\minilib")

$ErrorActionPreference = "Stop"
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$root = Split-Path -Parent $here
$runner = Join-Path $root "tools\run_cases.exe"

if (-not (Test-Path $runner)) {
    Write-Error "run_cases.exe not found at $runner -- build it first (see this script's header)."
    exit 1
}

$failed = 0
foreach ($fixture in @("m3.expected.txt", "m3_extra.expected.txt")) {
    $path = Join-Path $here "fixtures\cases\$fixture"
    $out = @(& $runner ($Minilib -replace "\\", "/") $path)
    $out | ForEach-Object { Write-Host $_ }
    if ($LASTEXITCODE -ne 0) { $failed++ }
}
if ($failed -eq 0) {
    Write-Host "PASS: every case matches the reference"
    exit 0
}
Write-Host "FAIL: $failed fixture(s) had mismatches"
exit 1
